               shortcut: "Pre-fried tofu puffs from an asian grocery skip the frying entirely and soak up even more sauce, though the insides are airier than fresh-fried."),
        Recipe(dishID: "vietnam-chetroinuoc", serves: 6, prepMinutes: 50, cookMinutes: 30, difficulty: 3,
               ingredients: [
                   RecipeIngredient(amount: "1/2 cup", item: "dried split mung beans (yellow, skinless)"),
                   RecipeIngredient(amount: "5 tbsp", item: "sugar, divided"),
                   RecipeIngredient(amount: "a pinch", item: "salt"),
